bool PreferencesWindow::on_page_message(const std::string& type, const json& payload)
{
    if (type == Agent::Protocol::kShellAction && payload.is_object() && payload.value("action", std::string()) == "close") {
        // The page closes a window opened for one task once it is done. A key
        // counts only once one is stored and the agent is on.
        AfterClose after;
        const std::string done = payload.value("done", std::string());
        if (m_request.close_when_done &&
            (done == "tool" || (done == "key" && wxGetApp().app_config->get("jusprin_agent", "enabled") == "true")))
            after.done = done;
        CallAfter([this, after] { close_for(after); });
        return true;
    }
    if (type == Agent::Protocol::kShellAction && payload.is_object() && payload.value("action", std::string()) == "open_pricing") {
        // Account's Get more credits, as the composer's opens it.
        wxLaunchDefaultBrowser(wxString::FromUTF8(Agent::cloud_pricing_url(wxGetApp().app_config)));
        return true;
    }
    if (type != Agent::Protocol::kPreferencesAction)
        return false;
    const Outcome outcome = apply_action(*wxGetApp().app_config, payload);
    if (!outcome.error.empty())
        BOOST_LOG_TRIVIAL(warning) << "JusPrin Preferences refused an action: " << outcome.error;
    // The page draws what is stored, so a refused change springs back.
    push_state();
    if (outcome.error.empty() && outcome.effect != Effect::None) {
        // Not from inside the web view's message handler: some of these open
        // a modal dialog or close this window.
        CallAfter([this, outcome] { carry_out(outcome); });
    }
    return true;
}

