    wxWindow*              next_focus(const wxWindow* from, bool backward) const;
    void                   move_focus(bool backward);

private:
    wxWindow* build_header(const ShellPalette& palette);
    wxString context_text() const;
    void     fill_report();
    void     show_finding(const CheckRow& row);
    void     on_frame();
